SELECT Students.CC, Students.[DS#], Family.FormID, Students.Name, Students.CurrentClass, Students.CurrentSection, Family.FatherName, Family.Mobile, Family.PhHome, Family.Mcell, Count(*) AS Months, Sum([TuitionFee])+Sum([Mis_fee])+Sum([AdmissionFee])+Sum([other])+Sum([ProspectusFee])+Sum([Fine])+Sum([ExamsFee]) AS TOTAaL, Sum(Feerecipt.TuitionFee) AS SumOfTuitionFee, Sum(Feerecipt.ExamsFee) AS SumOfExamsFee, Sum(Feerecipt.Mis_fee) AS SumOfMis_fee, Sum(Feerecipt.AdmissionFee) AS SumOfAdmissionFee, Sum(Feerecipt.ProspectusFee) AS SumOfProspectusFee, Sum(Feerecipt.Fine) AS SumOfFine, Sum(Feerecipt.Other) AS SumOfOther, Departments.DeptNo, "92" & Right([Mobile],10) AS cellno, Family.PhOffice, Departments.DepartN, Departments.Br_ID, Branches.Address, qryLastPaymentDate.MaxOfReDate
FROM (Branches INNER JOIN Departments ON Branches.BrID = Departments.Br_ID) INNER JOIN (Family INNER JOIN (((Classes INNER JOIN Students ON Classes.ClassID = Students.CurrentClass) INNER JOIN qryLastPaymentDate ON Students.CC = qryLastPaymentDate.CC) INNER JOIN Feerecipt ON Students.CC = Feerecipt.CC) ON Family.FormID = Students.FamilyID) ON Departments.DeptNo = Classes.DeptNo
WHERE (((Feerecipt.Paid)=False) AND ((Students.Status)=True))
GROUP BY Students.CC, Students.[DS#], Family.FormID, Students.Name, Students.CurrentClass, Students.CurrentSection, Family.FatherName, Family.Mobile, Family.PhHome, Family.Mcell, Departments.DeptNo, "92" & Right([Mobile],10), Family.PhOffice, Departments.DepartN, Departments.Br_ID, Branches.Address, qryLastPaymentDate.MaxOfReDate
HAVING (((Count(*))>3))
ORDER BY Students.CurrentClass, Count(*) DESC;

